INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 48, 'theory', 'Quiz: passwords and sessions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 0, 'Why are passwords hashed rather than encrypted?', '["Encryption is slower", "The encryption key leaks along with the database; a hash is irreversible", "Hashes are shorter", "It is simply easier to write the code"]', 1, 'A cipher is reversible given the key; a salted hash cannot be recovered, only brute-forced.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 1, 'Why is a salt added to the password before hashing?', '["So identical passwords produce different hashes and precomputed tables do not work", "To speed up verification", "To make the password shorter", "The salt is the server''s secret key"]', 0, 'The salt is random and stored next to the hash; it is not a secret, but it ruins attacks based on precomputed tables.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 2, 'What should login return for an unknown name and for a wrong password?', '["Different error texts", "The same 401 response with the same text", "404 for an unknown name", "500"]', 1, 'Different responses reveal which names exist (user enumeration).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 3, 'What does the sessions table store instead of the token itself?', '["The user''s password", "The token''s hash", "The salt", "Nothing"]', 1, 'Then a leaked table does not yield working tokens; the token is random, so a fast hash is enough for it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 4, 'Which code means "identity known, but the action is forbidden"?', '["401", "403", "404", "409"]', 1, '401 means not authenticated; 403 means authenticated but without permission.');
